// src/utils/jwt.ts
import jwt from "jsonwebtoken";
var createToken = (payload, secret, expiresIn) => {
  const token = jwt.sign(
    payload,
    secret,
    {
      expiresIn
    }
  );
  return token;
};
var verifyToken = (token, secret) => {
  try {
    const verifyToken2 = jwt.verify(token, secret);
    return {
      success: true,
      data: verifyToken2
    };
  } catch (error) {
    return {
      success: false,
      message: error.message,
      error
    };
  }
};
