// src/middlewares/auth.ts
import httpStatus3 from "http-status";
var auth = (...requiredRoles) => {
  return catchAsync(async (req, res, next) => {
    const token = req.cookies.accessToken ? req.cookies.accessToken : req.headers.authorization?.startsWith("Bearer ") ? req.headers.authorization?.split(" ")[1] : req.headers.authorization;
    if (!token) {
      throw new AppError(
        httpStatus3.UNAUTHORIZED,
        "You are not logged in. Please log in to access this resource."
      );
    }
    const verifiedToken = jwtUtils.verifyToken(token, config_default.jwt.secret);
    if (!verifiedToken.success) {
      throw new AppError(
        httpStatus3.UNAUTHORIZED,
        verifiedToken.message || "Invalid or expired token."
      );
    }
    const { id, role } = verifiedToken.data;
    if (requiredRoles.length && !requiredRoles.includes(role)) {
      throw new AppError(
        httpStatus3.FORBIDDEN,
        "Forbidden. You don't have permission to access this resource.",
        {
          requiredRoles,
          yourRole: role
        }
      );
    }
    const user = await prisma.user.findUnique({
      where: { id }
    });
    if (!user) {
      throw new AppError(
        httpStatus3.NOT_FOUND,
        "User not found. Please log in again."
      );
    }
    if (user.status === "BANNED") {
      throw new AppError(
        httpStatus3.FORBIDDEN,
        "Your account has been banned. Please contact support.",
        { status: user.status }
      );
    }
    req.user = {
      email: user.email,
      name: user.name,
      id: user.id,
      role: user.role
    };
    next();
  });
};

